  aria:         { n: 'Aria e gas nel motore', c: 0x4fc3f7 },
  carburante:   { n: 'Carburante', c: 0xffd54f },
  idraulico:    { n: 'Impianto idraulico', c: 0x26c6da },
  elettrico:    { n: 'Impianto elettrico', c: 0x8c9eff },
  olio:         { n: 'Lubrificazione (olio)', c: 0xffb300 },
