// id: { k: componente chiave (etichetta sempre visibile), n: nome, s: impianti, d: scheda }
// fonti delle cifre: vault UH-169 Lab/Fatti pubblici verificati (TCDS EASA R.509, CAA, AAIB 1/2023, P&W, Leonardo)
var DATA = {
  // ---- struttura ----
  fusoliera: { k: 1, n: 'Fusoliera e trave di coda', s: ['struttura'], d: 'Fusoliera lunga 12,19 m, larga 2,15 m e alta 3,88 m; con i rotori in moto l’elicottero è lungo 14,65 m e alto 4,5 m. La cabina ha il pavimento piano e grandi porte scorrevoli, pensate per barelle e carichi. Il tetto porta la trasmissione principale e i due motori, sotto la fila posteriore della cabina ci sono i serbatoi; dietro, la trave di coda porta l’albero di coda, la deriva, lo stabilizzatore e il rotore di coda. Varianti militari e governative: Esercito Italiano (UH-169B addestrativo a ruote, UH-169D AW169MA su pattini), Bundesheer austriaco (AW169B e AW169MA Lion), Carabinieri (UH-169C) e Guardia di Finanza (UH-169A a ruote e MH-169A su pattini con sistema ATOS, radar Gabbiano ed EO/IR LEOSS).' },
  vetri: { n: 'Vetrature di cabina', s: ['cabina', 'struttura'], d: 'Parabrezza e finestrini della cabina di pilotaggio e della cabina. Danno al pilota la visuale in avanti, di lato e verso il basso che serve in volo stazionario e negli atterraggi in aree ristrette.' },
  porte: { n: 'Porte', s: ['struttura', 'cabina'], d: 'Porte di pilotaggio incernierate sul bordo anteriore e porte scorrevoli della cabina, che escono di qualche centimetro e scorrono all’indietro su due binari. Si aprono dal pulsante Porte.' },
  cofano: { n: 'Cofani motori e trasmissione', s: ['struttura', 'motore'], d: 'Carenatura sul tetto che copre MGB e motori: protegge gli impianti e guida l’aria verso le prese. I pannelli si aprono per l’ispezione prima del volo e per la manutenzione. Con lo spaccato acceso il modello la taglia a metà per mostrare cosa c’è sotto.' },
  deriva: { k: 1, n: 'Deriva', s: ['struttura'], d: 'Superficie verticale in coda. In volo avanzato il suo profilo dà una forza laterale che contrasta parte della coppia del rotore principale, e così scarica il rotore di coda; in volo stazionario il lavoro resta tutto al rotore di coda. In cima porta il riduttore e il rotore di coda.' },
  stabilizzatore: { n: 'Stabilizzatore orizzontale', s: ['struttura'], d: 'Superficie orizzontale sulla trave di coda. In volo avanzato dà stabilità di beccheggio e tiene la fusoliera in un assetto vicino all’orizzontale. Le due configurazioni differiscono: sull’UH-169B a ruote monta piccole alette d’estremità rivolte verso l’alto; sull’UH-169D (AW169MA su pattini) lo stabilizzatore è ridisegnato con ampie piastre verticali d’estremità (endplate) a freccia inclinate leggermente verso l’interno, estese sopra e sotto il bordo d’uscita, più una pinna ventrale asimmetrica sotto il cono della trave di coda (brochure AW169M).' },
  sponson: { n: 'Sponson laterali (UH-169B)', s: ['struttura'], d: 'Carenature aerodinamiche ai lati della fusoliera inferiore: appartengono solo alle versioni con carrello retrattile a ruote (UH-169B / AW169B / UH-169A), dove accolgono le gambe principali retratte. Sull’UH-169D (e sulle varianti militari su pattini come AW169MA e MH-169A) gli sponson non ci sono.' },
  ruote: { k: 1, n: 'Carrello a ruote retrattile (UH-169B)', s: ['struttura'], d: 'Carrello triciclo a retrazione elettrica (dato di certificazione, TAR AW169): anteriore a due ruote gemellate sotto il muso, principale a una ruota per lato sotto gli sponson. In volo di trasferimento rientra e riduce la resistenza: l’anteriore all’indietro nel vano sotto la cabina di pilotaggio, il principale in avanti dentro gli sponson. Ogni gamba principale ha un controvento che a carrello giù è dritto e la tiene, poi si piega quando la gamba sale. A terra permette di rullare e di muovere l’elicottero senza sollevarlo. Carreggiata e diametri dalla 3-vista; perni, corse e cinematica sono illustrativi (il disegno Leonardo non è pubblico).' },
  attuatori_carrello: { k: 1, n: 'Attuatori elettrici del carrello', s: ['struttura', 'elettrico'], d: 'Il carrello dell’AW169 si muove con attuatori elettrici, non idraulici (TAR AW169). Nel modello un attuatore lineare per gamba: un motore elettrico gira una vite che allunga o accorcia lo stelo e ruota la gamba attorno al suo perno. Prende corrente dalla barra: senza alimentazione il carrello resta dov’è. Corsa di circa 8 s; numero, posizione, tempi e assorbimento sono illustrativi.' },
  portelli_carrello: { n: 'Portelli del carrello', s: ['struttura'], d: 'Chiudono i vani a carrello retratto. Nel modello sono legati alle gambe: quello del principale è fissato alla gamba e chiude il lato dello sponson, i due dell’anteriore si aprono nel primo terzo della corsa e restano aperti a carrello giù. Disposizione illustrativa.' },
  s_wow: { n: 'Sensore di peso sulle ruote (WoW)', s: ['struttura', 'fadec'], d: 'Weight on wheels: sente se le ruote portano il peso dell’elicottero. A terra inibisce il comando SU, così il carrello non può rientrare con l’elicottero appoggiato. Il rapporto AAIB su G-VSKP lo cita tra i sensori dell’AW169 e descrive la richiesta «gear up» durante la transizione dopo il decollo, con il carrello che rientra subito dopo. Nel simulatore «a terra» vuol dire collettivo sotto l’hovering o NR sotto il 90%.' },
  pattini: { k: 1, n: 'Pattini e gradini d’imbarco (UH-169D)', s: ['struttura'], d: 'UH-169D / AW169MA (e versioni su pattini come AW169MA Lion austriaco e MH-169A GdF): pattini fissi rinforzati al posto del carrello retrattile e degli sponson, con lunghi gradini esterni d’imbarco lungo il lato cabina. Adatti a terreni non preparati, neve e sabbia; non rientrano e per gli spostamenti a terra si montano ruote di movimentazione.' },
  // ---- cabina e cockpit (interno illustrativo: nessun disegno pubblico) ----
  cruscotto: { k: 1, n: 'Cruscotto (3 AMLCD: PFD/MFD + ISIS)', s: ['cabina', 'elettrico', 'avionica'], d: 'Plancia anteriore davanti ai piloti con architettura Honeywell Primus Epic (tre grandi schermi 8×10" condivisi come filosofia con AW139/AW189): PFD (Primary Flight Display) esterno per pilota e copilota con orizzonte ADI dinamico, anemometro IAS, altimetro barometrico/RA, bussola HSI e barra FLI (First Limit Indicator), più MFD centrale con fascia motori, finestra allarmi CAS (rosso Warning, ambra Caution, ciano Advisory) e pagine sinottiche selettive (STAT, ELEC, FUEL, HYD, ECS, FCS). Attorno: strumento di riserva ISIS, bussole magnetiche, leva carrello (su B), orologio, spie Master Warning/Caution e pannello AFCS sul parasole antiriflesso. Rappresentazione didattica fedele solo a fonti pubbliche.' },
  console: { k: 1, n: 'Console centrale (interseat, EDCU, ACP, DTD e Park Brake)', s: ['cabina', 'avionica'], d: 'Console tra i due sedili piloti (vista «Console»): nella parte alta inclinata ospita le due EDCU touchscreen (incluse pagine radio e interruttori allo stato solido SSPC / virtual CB); al centro i due pannelli audio ACP/ICS, il puntatore CCD, la tastiera, la porta/alloggiamento DTD (Data Transfer Device) per il caricamento dati missione/HUMS e, su UH-169B, la manopola indipendente del freno di parcheggio (PARK BRAKE); sul retro la leva rossa del freno rotore. Copre inoltre il pozzetto superiore della ruota anteriore retratta.' },
  pannello_sup: { n: 'Pannello superiore (overhead) con breaker fisici Hot/Emer', s: ['cabina', 'elettrico'], d: 'Sul soffitto tra i due piloti (inquadratura dedicata «Overhead» nel menu Viste): raggruppa interruttori elettrici (BSG 1/2, BATT 1/2), maniglie tagliafuoco e avviamento motori, pompa/valvole carburante, luci esterne, anti-ice e una fila compatta di interruttori termici fisici dedicata esclusivamente ai bus critici/caldi (Hot Bus, batteria, emergenza, antincendio). Tutti gli altri circuit-breaker sono invece virtuali allo stato solido (SSPC) gestiti su EDCU da PDU 1/2 e REPU. Disposizione illustrativa.' },
  sedili_piloti: { n: 'Sedili dei piloti', s: ['cabina'], d: 'Sedili ad assorbimento d’urto con cinture a quattro punti, cloche tra le gambe, collettivo alla sinistra e pedaliera sotto il cruscotto (comandi doppi collegati). Sull’UH-169D integrano protezioni balistiche laterali e di pavimento parte del kit SIAP. Forma, misure e posizione nel modello sono illustrative.' },
  rivestimenti: { n: 'Rivestimenti della cabina', s: ['cabina'], d: 'Pannelli interni di pareti, soffitto e porte. Dietro passano le aste dei comandi, il bus dati e i cavi elettrici tra BSG, BCU, PDU 1/2, nodi REPU e batterie, salendo lungo i montanti strutturali; nella parte posteriore e sopra il soffitto sono alloggiati rispettivamente le unità di distribuzione PDU/BCU e il mixer. In fondo un ripiano con due armadietti copre i serbatoi carburante e i loro sfiati. Con i raggi X o lo spaccato i rivestimenti spariscono come la pelle. Forma e colori illustrativi.' },
  sedili_cabina: { n: 'Sedili della cabina', s: ['cabina'], d: 'Cabina a pavimento piano con porte scorrevoli. Qui due file di tre su binari nel pavimento: una rivolta all’indietro dietro i piloti, una in avanti contro il ripiano che copre i serbatoi carburante. La disposizione reale cambia con la missione (passeggeri, barella, carico): numero e posizione dei sedili illustrativi.' },
  // ---- rotori ----
  rotore: { k: 1, n: 'Rotore principale (5 pale)', s: ['rotori'], d: 'Rotore completamente articolato a 5 pale, diametro 12,12 m, con smorzatori tra pala e pala. Pale in composito scuro grigio-ardesia con lamina metallica antierosione in titanio sul bordo d’attacco e punte a freccia ad alta visibilità (bande bianco-rosse sull’UH-169B, schema tattico attenuato sull’UH-169D, da immagini pubbliche). Il collettivo cambia insieme il passo di tutte le pale; i giri (NR) restano quasi costanti regolati dal FADEC.' },
  mozzo: { n: 'Mozzo del rotore', s: ['rotori'], d: 'Testa rotore completamente articolata: ogni pala ha tre movimenti, il passo (rotazione sul suo asse), il flappeggio (su e giù) e il ritardo (avanti e indietro nel piano del disco). Gli smorzatori tra le pale frenano il moto di ritardo ed evitano la risonanza a terra, un’oscillazione che può crescere fino a distruggere l’elicottero.' },
  piatto: { n: 'Piatto oscillante', s: ['rotori'], d: 'Due anelli: quello fisso è mosso dagli attuatori dei comandi di volo, quello rotante gira con il rotore e muove le aste di passo. Se il piatto sale o scende, tutte le pale cambiano passo insieme (collettivo); se si inclina, il passo varia lungo il giro e il disco si inclina (ciclico).' },
  manicotto: { n: 'Manicotto della pala', s: ['rotori'], d: 'Il manicotto collega la pala al mozzo: la sua forcella interna abbraccia il cuscinetto elastomerico, un pacco di lamine di gomma e acciaio che lascia alla pala i tre movimenti (passo, flappeggio, ritardo) senza cerniere da lubrificare. Sul lato del bordo d’attacco porta la squadretta a cui si attacca l’asta di passo: se l’asta sale, il bordo d’attacco sale e il passo cresce.' },
  smorzatore: { n: 'Smorzatori interpala', s: ['rotori'], d: 'Cinque smorzatori, ognuno tra un manicotto e il successivo. Frenano il moto di ritardo delle pale nel piano del disco: senza smorzamento, a terra, le pale fuori fase possono eccitare la risonanza a terra.' },
  aste_passo: { n: 'Aste di comando del passo', s: ['rotori'], d: 'Cinque aste verticali, una per pala, dal piatto rotante alla squadretta del manicotto. Il piatto che sale alza tutte le aste insieme (collettivo); il piatto inclinato le alza e abbassa una volta per giro (ciclico). Prova i comandi a rotore in moto: il passo massimo arriva circa 90° prima del punto dove il disco si alza di più.' },
  compasso: { n: 'Compassi', s: ['rotori'], d: 'Due bracci snodati a forbice. Quello rotante, tra albero e piatto rotante, fa girare il piatto con il rotore; quello fisso, tra MGB e piatto fisso, impedisce al piatto fisso di girare. Entrambi lasciano al piatto la libertà di salire e inclinarsi.' },
  servo_rotore: { n: 'Servoattuatori del rotore principale', s: ['rotori', 'idraulico', 'comandi'], d: 'Tre attuatori idraulici sulla MGB muovono il piatto fisso. Il comando arriva dal mixer con una biella al distributore di ognuno: tutti e tre insieme alzano il piatto, in modo diverso lo inclinano. Il pilota muove solo i distributori: senza pressione le aste si spostano ma il piatto resta fermo (prova a muovere i comandi a motori spenti). Ognuno ha due corpi in tandem sullo stesso stelo, uno per impianto idraulico: se un impianto perde pressione l’altro muove ancora il piatto. Le corse e gli angoli della simulazione sono illustrativi, non presi dal manuale.' },
  albero_rotore: { n: 'Albero rotore', s: ['rotori', 'trasmissione'], d: 'Albero verticale che esce dalla MGB e porta il mozzo. Trasmette la coppia al rotore e, nel verso opposto, porta alla struttura la portanza di tutto il rotore.' },
  rotore_coda: { k: 1, n: 'Rotore di coda (3 pale)', s: ['rotori'], d: 'Rotore di coda completamente articolato a 3 pale, diametro 2,40 m: pale in composito scuro con lamina antierosione in titanio sul bordo d’attacco e bande bianco-rosso-gialle ad alta visibilità alle estremità per sicurezza a terra (da foto ufficiali). La spinta laterale contrasta la coppia del rotore principale; con la pedaliera il pilota varia il passo (+25° / −10°, 1586 giri/min a NR 100%). È mosso dalla MGB quindi gira sempre con il rotore principale.' },
  // ---- trasmissione ----
  mgb: { k: 1, n: 'Trasmissione principale (MGB)', s: ['trasmissione', 'olio'], d: 'Riceve i due alberi dei motori, somma la potenza e riduce i giri a quelli del rotore; muove anche l’albero di coda. Ha un impianto olio proprio, con pompa mossa dalla trasmissione, radiatore e sensori di pressione e temperatura. È certificata per 33 minuti di funzionamento a secco, cioè dopo la perdita dell’olio: è un margine per raggiungere un’area di atterraggio, non un tempo da consumare.' },
  alb_motore: { n: 'Alberi di ingresso alla MGB', s: ['trasmissione'], d: 'Un albero per motore, dal riduttore anteriore del PW210A alla MGB. All’ingresso una ruota libera fa passare la coppia solo dal motore verso il rotore: se un motore si spegne o resta al minimo, il rotore non lo trascina e continua a girare mosso dall’altro motore, o in autorotazione.' },
  alb_coda: { n: 'Albero di trasmissione di coda', s: ['trasmissione'], d: 'Albero lungo la trave di coda, dalla MGB al riduttore intermedio, sostenuto da supporti con cuscinetti. Gira sempre con il rotore principale: se si rompe, il rotore di coda si ferma e si perde il controllo dell’imbardata.' },
  igb: { n: 'Riduttore intermedio (IGB)', s: ['trasmissione'], d: 'Alla base della deriva: cambia la direzione dell’albero di coda, che sale lungo la deriva verso il riduttore di coda.' },
  tgb: { n: 'Riduttore di coda (TGB)', s: ['trasmissione'], d: 'In cima alla deriva: riduce i giri e gira il moto di 90°, verso il mozzo del rotore di coda che ha l’asse trasversale.' },
  ruota_libera: { n: 'Ruote libere', s: ['trasmissione'], d: 'Una per motore, all’ingresso della MGB: giunto a senso unico, la metà lato motore trascina la metà lato MGB ma non viceversa. Col motore al minimo e il rotore a regime le due metà girano a velocità diverse: il motore è svincolato. Nel modello le due metà hanno colori diversi per vedere lo svincolo.' },
  freno_rotore: { n: 'Freno rotore', s: ['trasmissione'], d: 'Disco sull’uscita della MGB verso la coda, con una pinza idraulica fissa. Ferma il rotore dopo lo spegnimento e lo tiene fermo in modalità APU, quando il motore 1 gira per dare elettricità, aria e pressione idraulica ma non deve trascinare il rotore. Bloccando l’albero di coda blocca anche il rotore principale, perché sono uniti dagli ingranaggi della MGB. Nel simulatore la pinza si accende quando il freno è inserito (modalità APU).' },
  giunti_coda: { n: 'Giunti flessibili dell’albero di coda', s: ['trasmissione'], d: 'Tra un tratto e l’altro dell’albero di coda: pacchi di lamelle che trasmettono la coppia ma si flettono, così l’albero segue le piccole deformazioni della trave in volo senza forzare i cuscinetti. Il disegno dei giunti e il numero dei tratti nel modello sono illustrativi.' },
  supporti_coda: { n: 'Supporti dell’albero di coda', s: ['trasmissione'], d: 'Cuscinetti fissati alla trave che tengono l’albero allineato. Si controllano per gioco, rumore e temperatura: un cuscinetto che si guasta scalda e può danneggiare l’albero.' },
  ventola_olio: { n: 'Ventola del radiatore olio MGB', s: ['trasmissione', 'olio'], d: 'Ventola mossa dall’albero di coda che spinge aria attraverso il radiatore dell’olio della MGB: gira sempre col rotore, quindi raffredda l’olio anche con un motore spento. La posizione nel modello è illustrativa.' },
  passo_coda: { n: 'Comando del passo del rotore di coda', s: ['rotori', 'comandi'], d: 'L’albero di comando, che non gira, passa dentro lo stelo cavo del pistone del TRA e nel TGB e sposta il ragno fuori dal mozzo; il ragno gira col rotore e con tre bielle muove il retro delle pale, che cambiano passo tutte insieme. Il passo va da +25° a −10° (al 75% del raggio), limitato dai fermi primari; il rotore di coda fa 1586 giri/min con NR al 100%. Fonte: rapporto AAIB 1/2023. Prova lo slider PEDALIERA.' },
  servo_coda: { n: 'Attuatore del rotore di coda (TRA)', s: ['rotori', 'idraulico', 'comandi'], d: 'Sul TGB, dalla parte opposta al rotore. Due corpi, uno per ognuno dei due impianti idraulici indipendenti, con le forze che si sommano: forza di stallo 25 780 N con due impianti, 12 760 N con uno solo (fonte AAIB). Il comando arriva dalla leva d’ingresso al distributore (la scatola sotto il corpo); senza pressione lo stelo resta fermo.' },
  pedaliera: { n: 'Pedaliera', s: ['cabina', 'comandi'], d: 'Due coppie di pedali, una per pilota, collegate tra loro: quando un pedale avanza l’altro arretra. Cambiano il passo del rotore di coda, cioè la sua spinta laterale. Il rotore principale gira in senso antiorario visto dall’alto, quindi la coppia fa girare il muso a destra: in hovering serve pedale sinistro, che dà più passo. Prova lo slider PEDALIERA. Posizione e forma dei pedali nel modello sono illustrative.' },
  cavo_coda: { n: 'Cavo flessibile del comando di coda', s: ['comandi'], d: 'Dalla pedaliera alla base della deriva il comando corre in un cavo flessibile a sfere dentro una guaina, lungo la fusoliera: spinge e tira come un’asta, ma segue le curve. Ai due capi si vede l’anima che scorre fuori dalla guaina. Sull’AW169 è così (fonte: rapporto AAIB 1/2023); il percorso nel modello è illustrativo.' },
  squadretta_coda: { n: 'Squadretta con i fermi primari', s: ['comandi'], d: 'Alla base della deriva gira il moto del cavo verso l’asta che sale nella deriva. Porta i fermi primari (i blocchetti rossi): limitano la corsa dei pedali e quindi il passo delle pale di coda tra +25° e −10°. Prova la PEDALIERA ai due estremi: un braccio della squadretta arriva sul fermo.' },
  asta_coda: { n: 'Asta lunga e rinvio', s: ['comandi'], d: 'Asta rigida che sale dentro la deriva dalla squadretta fino al TGB. Il rinvio sotto il TGB (forma illustrativa) gira il moto nella direzione dell’asse del rotore di coda e con una biella lo porta alla leva d’ingresso del TRA.' },
  leva_tra: { n: 'Leva d’ingresso del TRA', s: ['comandi', 'idraulico'], d: 'Leva con tre attacchi: in basso la biella che viene dai pedali, al centro il distributore del TRA, in alto l’albero di comando, fissato con perno e dado a corona. Il pedale sposta il capo basso: la leva ruota attorno a quello alto e apre il distributore. Il pistone sposta l’albero e con lui il capo alto: la leva ruota attorno a quello basso e richiude il distributore. È la retroazione: il passo si ferma dove lo chiedono i pedali. Se il dado si svita l’albero si stacca dalla leva, la retroazione sparisce e il TRA va a fondo corsa (avaria del cuscinetto duplex).' },
  cuscinetto_duplex: { n: 'Cuscinetto duplex', s: ['comandi', 'rotori'], d: 'Collega l’albero di comando, che non gira, al ragno, che gira col rotore di coda: anello interno fermo sull’albero, esterno nel ragno. Due corone di sfere schiena contro schiena, con le piste inclinate di circa 30°, perché l’albero spinge e tira. Su G-VSKP (Leicester, 27/10/2018) si grippò: l’albero cominciò a girare e svitò il dado che lo teneva alla leva, le pale andarono al fermo negativo e l’elicottero imbardò a destra senza controllo. Dopo l’incidente il dado ha il filetto sinistro (AD EASA 2020-0048). Fonte: rapporto AAIB 1/2023. Prova l’avaria.' },
  compasso_coda: { n: 'Compassi del rotore di coda', s: ['comandi', 'rotori'], d: 'Bracci snodati a forbice tra il mozzo e il ragno: fanno girare il ragno con il rotore e lo lasciano scorrere lungo l’asse quando l’albero di comando lo spinge o lo tira. Prova la PEDALIERA: i compassi si aprono e si chiudono. Fonte AAIB 1/2023 («scissor assemblies»); numero e forma nel modello illustrativi.' },
  cloche: { n: 'Cloche (comando ciclico)', s: ['cabina', 'comandi'], d: 'Una per pilota, tra le gambe, unite sotto il pavimento da una barra: si muovono insieme. Avanti e indietro inclina il disco del rotore in avanti e indietro, a destra e sinistra lo inclina di lato, e l’elicottero va dove si inclina il disco. Sotto il perno la cloche si muove al contrario e spinge due canali di aste: longitudinale e laterale. Sull’AW169 i comandi sono meccanici con servi idraulici (fonte AAIB 1/2023); posizione e leveraggi nel modello illustrativi. Prova i due slider del CICLICO.' },
  collettivo: { n: 'Leva del collettivo', s: ['cabina', 'comandi'], d: 'Una per pilota, alla sua sinistra, unite da un tubo di torsione sotto i sedili. Alzandola tutte le pale prendono più passo insieme: più portanza e più coppia chiesta ai motori. La leva ha un attrito regolato: un AD EASA (2017-0137) prescrive di controllarlo perché con attrito troppo basso in hovering il collettivo può oscillare. Sul tubo un braccio spinge il canale del collettivo. Leveraggi illustrativi. Prova lo slider COLLETTIVO.' },
  aste_comando: { n: 'Aste e squadrette dei comandi', s: ['comandi'], d: 'Tre canali di aste rigide che spingono e tirano: longitudinale e laterale dalla cloche, collettivo dalla leva. Corrono sotto il pavimento, salgono dietro i piloti e vanno lungo il soffitto fino al mixer sotto la MGB; agli angoli le squadrette girano il moto. Dal mixer tre aste salgono ai servi. Che i comandi siano meccanici è dato pubblico (AAIB 1/2023); il percorso reale è solo nei manuali Leonardo: qui è illustrativo.' },
  mixer: { n: 'Mixer dei comandi', s: ['comandi'], d: 'Unità di leve che riceve i tre canali (collettivo, longitudinale, laterale) e li trasforma nei comandi dei tre servi. Il collettivo muove i tre servi della stessa corsa (il piatto sale o scende); il ciclico li muove in modo diverso, secondo la posizione di ognuno attorno all’albero (il piatto s’inclina). Così ogni servo riceve la quota che il piatto deve avere sopra di lui. Forma e posizione illustrative: il mixer dell’AW169 non è descritto nelle fonti pubbliche.' },
  attuatori_afcs: { n: 'Attuatori dell’AFCS', s: ['comandi', 'elettrico'], d: 'L’AFCS dell’AW169 è digitale a 4 assi (beccheggio, rollio, imbardata, collettivo: fonte AAIB 1/2023). L’autopilota agisce sulle stesse aste dei piloti con piccoli attuatori elettrici: qui uno in serie in ognuno dei tre canali del rotore principale, che allunga o accorcia l’asta di poco senza muovere la cloche. Numero, tipo e posizione illustrativi; l’attuatore dell’imbardata non è disegnato.' },
  fcc: { n: 'Calcolatore dei comandi di volo (FCC)', s: ['comandi', 'avionica', 'elettrico'], d: 'Il cuore dell’AFCS a 4 assi nel muso: due canali ridondanti (AP1 e AP2) con architetture dissimili all’interno per tollerare errori di progetto; dialoga con ADAHRU e AMMC su bus dati digitali (fonte AAIB 1/2023; forma e sede esatta nel modello illustrative).' },
  adahru: { n: 'ADAHRU / ADU e sonde dati aria', s: ['comandi', 'avionica', 'elettrico'], d: 'Due unità integrate dati aria / assetto / prua (ADAHRU) collegate alle sonde esterne Pitot-statiche e TAT sui fianchi del muso: alimentano PFD, standby e FCC (il bus arresta l’AFCS sopra 128°/s d’imbardata come su G-VSKP — fonte AAIB 1/2023; forma e quote illustrative).' },
  bus_dati: { n: 'Bus dati AFCS e avionica', s: ['comandi', 'avionica', 'elettrico'], d: 'Dorsali digitali che collegano ADAHRU, AMMC, FCC e attuatori AFCS tra muso e ponte superiore (percorso illustrativo).' },
  // ---- motori PW210A (stessi pezzi nei due motori) ----
  pw1: { k: 1, n: 'Motore 1 (PW210A, sinistro)', s: ['motore'], d: 'Turboalbero a turbina libera classe 1000 shp, della famiglia PW210 di Pratt & Whitney Canada (sull’AW169 la versione PW210A). Due parti: il generatore di gas (compressore, camera, HPT, giri NG) produce gas caldi in pressione; la turbina libera (giri NP) li trasforma in potenza all’albero. È il motore 1, a sinistra: in modalità APU è quello che resta acceso al minimo.' },
  pw2: { k: 1, n: 'Motore 2 (PW210A, destro)', s: ['motore'], d: 'Secondo PW210A, identico al motore 1, a destra. Ognuno ha il suo FADEC e i due si dividono il carico. Se un motore si spegne (OEI), l’altro porta da solo il rotore con limiti più alti, per un tempo limitato. I valori del simulatore sono illustrativi.' },
  rgb: { k: 1, n: 'Riduttore anteriore e scatola accessori', s: ['motore', 'trasmissione'], d: 'Davanti al motore. Il riduttore porta i giri della turbina libera a quelli dell’albero di uscita verso la MGB. È unito alla scatola accessori, mossa dal generatore di gas, che porta le pompe di carburante e olio e l’avviatore-generatore. Qui c’è anche il sensore di coppia.' },
  presa: { n: 'Presa d’aria radiale con rete', s: ['motore', 'aria'], d: 'L’aria entra dai lati attraverso una rete che ferma i corpi estranei, poi una camera anulare la gira verso l’asse e la porta al compressore. Con la presa radiale il riduttore può stare davanti e il motore resta corto.' },
  comp_misto: { n: 'Compressore a flusso misto', s: ['motore', 'aria'], d: 'Primo stadio del compressore, a flusso misto: l’aria esce in parte verso l’esterno, tra assiale e centrifugo. A monte le VIGV, palette a calettamento variabile, orientano l’aria in ingresso: chiuse ai bassi giri evitano lo stallo, aperte a potenza lasciano passare tutta l’aria.' },
  comp_centr: { k: 1, n: 'Compressore centrifugo', s: ['motore', 'aria'], d: 'Secondo stadio: la girante centrifuga lancia l’aria verso l’esterno ad alta velocità, il diffusore la rallenta e la trasforma in pressione. Due soli stadi per tutto il rapporto di compressione: una soluzione compatta e robusta contro i corpi estranei, tipica dei piccoli turboalbero.' },
  diffusore: { n: 'Diffusore', s: ['motore', 'aria'], d: 'Canali che si allargano all’uscita della girante: la velocità cala e la pressione sale. Poi l’aria gira all’indietro verso la camera di combustione.' },
  camera: { k: 1, n: 'Camera di combustione a flusso inverso', s: ['motore', 'aria'], d: 'Camera anulare avvolta attorno alle turbine. L’aria del compressore scorre all’indietro lungo l’esterno della camera, entra dai fori, si mescola al carburante degli iniettori in fondo e brucia andando in avanti; all’uscita i gas girano di 180° ed entrano nella HPT. Così il motore resta corto e gli alberi corti sono più rigidi.' },
  hpt: { k: 1, n: 'Turbina del generatore di gas (HPT)', s: ['motore', 'aria'], d: 'Turbina monostadio: estrae dai gas l’energia che muove il compressore e la scatola accessori. Le sue pale lavorano nei gas più caldi del motore, per questo il FADEC ne limita la temperatura (TOT). I giri del generatore di gas sono NG, in percentuale.' },
  pt: { k: 1, n: 'Turbina libera (2 stadi)', s: ['motore', 'aria', 'trasmissione'], d: 'Due stadi senza collegamento meccanico con il generatore di gas: i gas la mettono in rotazione e lei muove, tramite il riduttore, l’albero di uscita. I suoi giri (NP) sono legati a NR dalla trasmissione e il FADEC li tiene costanti variando il carburante, cioè NG. Per questo all’avviamento il generatore di gas può girare anche con il rotore fermo.' },
  alb_ng: { n: 'Albero del generatore di gas', s: ['motore'], d: 'Albero cavo che collega la HPT al compressore e alla scatola accessori: gira a NG. All’avviamento è l’avviatore a farlo girare.' },
  alb_pt: { n: 'Albero della turbina libera', s: ['motore', 'trasmissione'], d: 'Passa dentro l’albero del generatore di gas e porta la potenza della turbina libera in avanti, al riduttore anteriore. Gira a NP, indipendente da NG.' },
  scarico: { n: 'Scarico', s: ['motore', 'aria'], d: 'Condotto che porta fuori dal cofano i gas usciti dalla turbina libera, ancora caldi ma a bassa pressione: quasi tutta la loro energia è già diventata potenza all’albero, quindi la spinta che resta è trascurabile.' },
  avv_gen: { n: 'BSG (starter-generatori brushless) 1 e 2', s: ['motore', 'fadec', 'elettrico'], d: 'Un BSG (Brushless Starter Generator) per motore sulla scatola accessori dei PW210A, pilotato elettronicamente dalla rispettiva BCU: all’avviamento funziona da motore per far girare il generatore di gas (escluso al 50% di NG), poi diventa generatore a 28 V cc senza spazzole sulle barre principali.' },
  // ---- carburante ----
  serbatoi: { k: 1, n: 'Serbatoi carburante (profilo a L)', s: ['carburante'], d: 'Due serbatoi principali, sinistro (LH) e destro (RH), nel retro della cabina passeggeri sotto la fila posteriore: 1130 L totali (904 kg a 0,8), di cui 20 L inutilizzabili (EASA TCDS R.509). Dalla fig. 17 del rapporto AAIB G-VSKP ciascun serbatoio ha profilo ribassato a L / gradino con pozzetto collettore anteriore e lobo superiore arretrato nella paratia: sacca in tessuto gommato antistrappo dentro guscio composito e schiuma ad alta densità (prova di caduta CS 29.952 da 15,2 m; autosigillanti nelle versioni militari M). Il giallo mostra il livello del carburante; sagoma esatta al millimetro illustrativa.' },
  p_carb: { n: 'Linee carburante', s: ['carburante'], d: 'Una linea per motore: dal fondo del serbatoio del suo lato, attraverso la valvola d’intercettazione, alla pompa sul motore, poi al regolatore (FCU) e agli iniettori. Nel modello aspira la pompa mossa dal motore, senza pompe elettriche nei serbatoi: le fonti pubbliche non ne parlano. Percorsi illustrativi.' },
  val_carb: { n: 'Valvole d’intercettazione', s: ['carburante'], d: 'Una per motore, chiudono il carburante prima del vano motore: le norme di certificazione (CS 29.1189) le chiedono, per esempio per isolare un motore in fiamme. Nel modello sono aperte con il selettore del motore su MIN o VOLO. Posizione e comando illustrativi.' },
  tubo_carb: { n: 'Tubo di collegamento dei serbatoi', s: ['carburante'], d: 'In basso, tra i due serbatoi: il carburante passa da quello più pieno all’altro e i livelli restano pari, anche con un solo motore acceso (rapporto AAIB sull’incidente di G-VSKP). Le comete danno il verso del travaso. Diametro e portata illustrativi.' },
  sfiati: { n: 'Sfiati dei serbatoi', s: ['carburante'], d: 'Due linee, una per serbatoio, con l’uscita sotto il ventre: fanno rientrare aria al posto del carburante consumato e scaricano i vapori. Le comete azzurre sono l’aria che entra. Se si ostruiscono tutte e due, com’è successo con sigillante in eccesso (AD EASA 2021-0238), l’aria non entra: nei serbatoi si crea depressione, le pompe dei motori non riescono più ad aspirare e si possono spegnere entrambi i motori. Percorsi illustrativi.' },
  s_carb: { n: 'Sonde di livello carburante', s: ['carburante', 'fadec'], d: 'Una per serbatoio: misurano la quantità di carburante, che gli strumenti mostrano in kg per serbatoio e in totale, con la portata consumata dai due motori. Sotto 60 kg in un serbatoio il simulatore avvisa CARBURANTE BASSO (soglia illustrativa).' },
  fcu: { k: 1, n: 'Regolatore carburante (FCU)', s: ['carburante', 'fadec', 'motore'], d: 'Sul motore: pompa ad alta pressione e dosatore. Il FADEC calcola la portata, il dosatore la manda agli iniettori. In avviamento apre il carburante al 12% di NG (valore del simulatore, illustrativo); in volo è dosando il carburante che il FADEC tiene costanti NP e NR.' },
  iniettori: { n: 'Iniettori', s: ['carburante', 'motore'], d: 'In fondo alla camera: polverizzano il carburante in goccioline fini, che evaporano e si mescolano all’aria. Una cattiva polverizzazione dà avviamenti difficili e punti caldi nella camera e sulla turbina.' },
  // ---- olio ----
  pompe_idr: { k: 1, n: 'Pompe idrauliche', s: ['idraulico', 'trasmissione'], d: 'L’AW169 ha due impianti idraulici indipendenti (dato Leonardo). Ogni impianto ha la sua pompa, mossa dagli ingranaggi accessori della MGB: gira con il rotore, quindi dà pressione anche con un motore spento e in autorotazione. In modalità APU, a rotore frenato, la muove il motore 1: Leonardo dichiara che in APU il velivolo ha potenza elettrica e idraulica. Pompa a pistoni assiali a portata variabile: tiene costante la pressione e manda solo l’olio che i comandi chiedono. Nel modello posizione e pressione (206 bar) sono illustrative.' },
  modulo_idr: { n: 'Moduli di potenza idraulica', s: ['idraulico'], d: 'Uno per impianto: serbatoio dell’olio idraulico, filtri, accumulatore (la sfera) che copre i picchi di richiesta, valvole e sensori. Da qui partono le mandate ai servoattuatori. Posizione nel modello illustrativa.' },
  p_idr: { n: 'Linee idrauliche', s: ['idraulico'], d: 'Mandate dei due impianti, separate per tutto il percorso: dalla pompa al modulo, poi a ognuno dei tre servoattuatori del rotore principale e, lungo la trave e la deriva, all’attuatore del rotore di coda. Le comete corrono più veloci quando si muovono i comandi, cioè quando gli attuatori chiedono olio. Percorsi illustrativi, ritorni non disegnati.' },
  s_idr: { n: 'Sensori pressione idraulica', s: ['idraulico', 'fadec'], d: 'Uno per impianto, sul modulo di potenza. Pressione bassa con il rotore in moto vuol dire impianto perso: i comandi restano con l’altro, senza più riserva.' },
  // ---- elettrico ----
  batterie: { k: 1, n: 'Batterie principale e ausiliaria', s: ['elettrico'], d: 'Due batterie indipendenti dalla generazione normale, di serie al nichel-cadmio (il litio è un kit a parte). Danno la corrente per avviare il primo motore e, se i due generatori sono fuori linea, alimentano i carichi essenziali, compreso l’orizzonte di riserva, per almeno 30 minuti (dati di certificazione). Con un generatore in linea si ricaricano. Nel modello stanno nel muso e lavorano come una batteria sola: posizione, capacità e tensioni sono illustrative.' },
  barre_el: { k: 1, n: 'PDU (distribuzione 1/2 a stato solido)', s: ['elettrico'], d: 'Due PDU (Power Distribution Unit 1 e 2) nel vano avionico posteriore (architettura pubblica AW169): instradano la potenza 28 V cc dai BSG 1/2 e dalle batterie alle barre principali ed essenziali. Integrano gli interruttori elettronici allo stato solido SSPC programmabili, gestiti dalle EDCU al posto della maggior parte dei breaker termici meccanici.' },
  bcu: { k: 1, n: 'BCU (controllo starter-generatori) 1 e 2', s: ['elettrico', 'fadec'], d: 'Due BCU (Brushless Control Unit 1 e 2): regolano tensione, eccitazione, sequenza di avviamento e protezioni dei rispettivi BSG su motore 1 e motore 2 (fonti pubbliche architettura elettrica AW169).' },
  repu: { k: 1, n: 'REPU (nodi remoti di distribuzione)', s: ['elettrico'], d: 'Nodi REPU (Remote Electrical Power Unit, es. vano anteriore sotto cockpit e nodo cabin/utility) dotati di SSPC locali che alimentano e proteggono i carichi vicini alle utenze, riducendo peso e lunghezza dei cablaggi in rame.' },
  cavi_el: { n: 'Cavi e dorsali di potenza', s: ['elettrico'], d: 'Dai BSG 1/2 alle BCU, alle PDU 1/2 posteriori e verso le REPU / batterie anteriori. Le comete mostrano il verso della corrente: dal BSG alle PDU a motore acceso, verso il BSG in avviamento, e carica/scarica batterie.' },
  s_el: { n: 'Sensore di tensione e corrente', s: ['elettrico', 'fadec'], d: 'Tensione delle barre e corrente delle batterie. In un avviamento a batteria la tensione cala per lo spunto dell’avviatore, poi risale con i giri; con un generatore in linea è regolata a 28 V e la corrente di batteria diventa di carica. Batterie che scaricano a motori accesi vogliono dire generatori fuori linea.' },
  serb_olio: { n: 'Serbatoio olio motore', s: ['olio', 'motore'], d: 'Olio di un motore: lubrifica e raffredda cuscinetti e ingranaggi del motore e del riduttore anteriore. Una pompa mossa dalla scatola accessori lo manda in circolo, le pompe di recupero lo riportano al serbatoio. Ogni motore ha il suo impianto.' },
  p_olio: { n: 'Linee olio motore', s: ['olio'], d: 'Mandata dell’olio ai cuscinetti e al riduttore, ritorno al serbatoio. La pompa è mossa dal generatore di gas, quindi la pressione segue NG: al minimo è più bassa che in volo. Pressione bassa a motore acceso vuol dire cuscinetti a rischio.' },
  rad_olio: { k: 1, n: 'Radiatore olio MGB', s: ['olio', 'trasmissione'], d: 'Scambiatore aria-olio che raffredda l’olio della trasmissione principale. Posizione nel modello illustrativa.' },
  p_olio_mgb: { n: 'Linee olio MGB', s: ['olio', 'trasmissione'], d: 'Dalla coppa della MGB al radiatore e ritorno. La pompa è mossa dalla trasmissione, quindi gira solo con il rotore in moto. Una perdita svuota la coppa: la pressione crolla e la MGB comincia a lavorare a secco.' },
  // ---- FADEC e sensori ----
  eec: { k: 1, n: 'FADEC (EEC a 2 canali)', s: ['fadec', 'motore'], d: 'Centralina del FADEC, a 2 canali completi: se un canale si guasta, l’altro prende il controllo. Avvia e accende il motore da solo, tiene NP e NR costanti al variare del collettivo, divide il carico tra i due motori, limita la temperatura di turbina e interrompe l’avviamento sospeso. Nel simulatore il pilota sceglie solo OFF, minimo o volo.' },
  candele: { n: 'Candele di accensione', s: ['fadec', 'motore'], d: 'Due candele per motore, sulla camera di combustione: accendono la miscela durante l’avviamento e si escludono quando la fiamma si sostiene da sola. Nel simulatore il FADEC le inserisce all’8% di NG (illustrativo).' },
  s_ng: { n: 'Sensore NG', s: ['fadec'], d: 'Giri del generatore di gas, in percentuale. Con NR costante NG è l’indice della potenza: più collettivo, più NG.' },
  s_tot: { n: 'Termocoppie TOT', s: ['fadec'], d: 'Corona di termocoppie nei gas dopo la HPT: la media è la TOT. È la temperatura chiave del motore: si sorveglia in avviamento (avviamento caldo) e alle alte potenze, dove è il FADEC a limitarla.' },
  s_tq: { n: 'Sensore di coppia (TQ)', s: ['fadec', 'trasmissione'], d: 'Coppia all’uscita del motore, in percentuale. Con NR costante la coppia è la potenza: è il dato con cui si gestisce il volo. Con i due motori in volo i due TQ sono quasi uguali; se uno cala, il FADEC fa salire l’altro.' },
  s_nr: { n: 'Sensore NR', s: ['fadec', 'rotori'], d: 'Giri del rotore principale, in percentuale. Il FADEC li tiene al 100%: NR basso vuol dire potenza insufficiente per il collettivo chiesto.' },
  s_olio: { n: 'Sensori olio motore', s: ['fadec', 'olio'], d: 'Pressione e temperatura dell’olio motore. Il limite di pressione vale anche al minimo, dove la pressione è più bassa: lì un’avaria si vede prima.' },
  // ---- avionica e sicurezza (fonti pubbliche AAIB / TCDS / brochure) ----
  ammc: { k: 1, n: 'Calcolatori AMMC 1 e 2 (AMMS / HUMS)', s: ['avionica', 'fadec'], d: 'Doppia unità centrale AMMC (Aircraft & Mission Management Computer) dell’avionica AMMS: elabora dati volo, sinottici impianti, logica d’allarme e integra le schede VDAM di monitoraggio vibrazioni (HUMS) collegate alla porta DTD sulla console centrale. Fonte: rapporto AAIB 1/2023 G-VSKP (§ 1.6.15, fig. 19); posizione ed elettronica nel vano avionico illustrative.' },
  dtd: { k: 1, n: 'DTD (Data Transfer Device, interseat)', s: ['cabina', 'avionica'], d: 'Modulo e presa card installati sulla console interseat tra i due piloti: trasferisce piani di volo/dati missione verso gli AMMC e scarica i registri HUMS/manutenzione tramite memoria portatile dedicata. Posizione su interseat coerente con configurazione cockpit pubblica AW169; forma del modulo illustrativa.' },
  tss: { n: 'TSS-4100 (TCAS II e Mode S)', s: ['avionica'], d: 'Sistema integrato di sorveglianza traffico aereo (TCAS II) e transponder Mode S con antenne direzionali dorsale e ventrale: segnala traffico vicino e fornisce identificazione ATC/ADS-B; sull’UH-169D coopera con l’IFF M428. Fonte pubblica avionica AW169; sede nel modello illustrativa.' },
  elt_adelt: { n: 'ELT fisso e ADELT (CPI ejettabile)', s: ['avionica'], d: 'Trasmettitore di emergenza a 406 MHz con unità fissa e capsula automatica ejettabile ADELT (Automatic Deployable ELT / CPI) integrata sul dorso poppiero della fusoliera (visibile sulle foto ufficiali AW169M): in caso d’impatto o immersione si sgancia automaticamente e trasmette la posizione GPS ai soccorsi. Quote interne illustrative.' },
  cvfdr: { k: 1, n: 'CVFDR / DAFR (scatola nera con ULB e RIPS)', s: ['avionica'], d: 'Registratore combinato audio di cabina e dati di volo (CVFDR / DAFR) nella trave di coda (arancione alta visibilità): integra faro acustico subacqueo ULB (Underwater Locator Beacon) e batteria autonoma RIPS (Recorder Independent Power Supply). Fonte: rapporto AAIB 1/2023 G-VSKP (§ 1.11.1); alloggiamento esatto illustrativo.' },
  // ---- missione ed EW (UH-169D, solo dati pubblici) ----
  eaps: { k: 1, n: 'Filtri prese d’aria EAPS / IBF (UH-169D)', s: ['motore', 'aria', 'missione'], d: 'Filtri barriera d’ingresso (EAPS / Inlet Barrier Filter) davanti alle prese dei due PW210A per ambiente sabbioso o polveroso: proteggono compressore e palette dall’erosione da sabbia, polvere e detriti FOD (brochure AW169M / Donaldson). Sagoma nel modello illustrativa.' },
  mair: { k: 1, n: 'SIAP: MAIR, RWR SAGE e RALM (UH-169D)', s: ['missione', 'avionica'], d: 'Suite integrata di autoprotezione SIAP dell’UH-169D (dati pubblici Leonardo / programmi EI): sensori ottici distribuiti all’infrarosso MAIR (incluse le carenature laterali posteriori dietro il finestrino cabina visibili sulle brochure AW169M e sui lati del muso) per allarme missili e fuoco ostile, ricevitori di allarme radar RWR / SAGE ESM e sensori laser RALM. Posizione e numero teste nel modello illustrativi.' },
  chaff_flare: { k: 1, n: 'Lanciatori Chaff/Flare ECDS (UH-169D)', s: ['missione'], d: 'Dispensatori simmetrici di esche infrarosso (flare) e radar (chaff) integrati sui fianchi inferiori della fusoliera poppiera sotto la radice della trave di coda, in carenature aerodinamiche angolate di ~42° verso il basso e l’esterno con caricatori da 30 cartucce ciascuno, comandati dalla suite SIAP contro minacce a guida IR o RF (brochure AW169M).' },
  edcu: { k: 1, n: 'Doppie EDCU touchscreen (pedestallo)', s: ['cabina', 'avionica'], d: 'Due unità di controllo multifunzione touchscreen EDCU (Enhanced Display Control Unit) affacciate fianco a fianco sulla sezione inclinata superiore della console centrale (layout comune AW139 / AW169 / AW189): selezionano le pagine sinottiche MFD, radio COM/NAV, transponder, audio ICS ed ECS.' },
  ecs: { k: 1, n: 'Climatizzazione ECS / VCS (Liebherr)', s: ['cabina', 'aria'], d: 'Sistema di controllo ambientale dual-zone (cockpit e cabina, dati pubblici Liebherr / brochure AW169): combina un impianto frigorifero a ciclo di vapore (VCS con compressore e condensatore posteriori e griglie di sfiato superiori) per il raffreddamento — operativo anche a terra in modalità APU — con spillamento d’aria calda dai compressori per riscaldamento e disappannamento parabrezza (WSHLD DEMIST).' },
  ics: { n: 'Interfono ICS (2× ACP e AMU)', s: ['cabina', 'avionica'], d: 'Sistema di comunicazioni interne ICS con doppi pannelli audio ACP (Audio Control Panel) su console centrale, unità di gestione AMU posteriore e prese cuffie per piloti e cabina: gestisce radio militari/civili, interfono e modalità isolamento/emergenza.' },
  freni_idr: { k: 1, n: 'Impianto idraulico freni ruote (indipendente, UH-169B)', s: ['idraulico', 'struttura'], d: 'Circuito idraulico dedicato esclusivamente ai freni delle ruote principali e al freno di stazionamento (PARK BRAKE): completamente indipendente dagli impianti idraulici 1 e 2 dei comandi di volo (architettura Parker pubblica per AW169). Comprende serbatoio e accumulatore nel muso, cilindri master sulle pedaliere e tubazioni flessibili verso le pinze freno sulle gambe principali.' },
  radio_mil: { k: 1, n: 'Radio Leonardo, Link 16, IFF e cifrante (UH-169D)', s: ['missione', 'avionica'], d: 'Suite di comunicazioni militari e rete tattica dell’UH-169D (dati pubblici Leonardo / EI): doppie radio SDR multibanda SWave SRT-800 V/UHF, radio HF SRT-200 con la tipica antenna a barra («towel-bar») lungo il lato sinistro della trave di coda, terminale tattico Link 16 KOR-24A STT, interrogatore/transponder IFF M428 Mode 4/5 NATO e unità cifrante COMSEC/TRANSEC per traffico protetto, oltre a antenne a lama e cupolino SATCOM dorsale. Posizione interna dei rack illustrativa.' },
  wsps_eoir: { n: 'Torretta EO/IR, tagliacavi WSPS e blindatura (UH-169D)', s: ['missione', 'struttura'], d: 'Kit di missione dell’UH-169D: torretta elettro-ottica/infrarosso (EO/IR) sotto il muso, coltelli tagliacavi superiori e inferiori WSPS (Wire Strike Protection System) visibili nelle immagini ufficiali AW169M e protezioni balistiche su pavimento e sedili piloti (SIAP). Dimensioni e quote illustrative.' }
};

// avarie: le chiavi sono lette da step() in index.html
var FAULTS = {
  noign: 'Motore 1: nessuna accensione', hot: 'Motore 1: avviamento caldo', hung: 'Motore 1: avviamento sospeso',
  oilp: 'Motore 1: pressione olio bassa', flame: 'Motore 2: fiamma persa in volo', mgb: 'Perdita olio della MGB', idr1: 'Perdita impianto idraulico 1', gen1: 'Generatore 1 fuori linea', vent: 'Sfiati dei serbatoi ostruiti', duplex: 'Coda: cuscinetto duplex grippato', ecs: 'ECS: avaria compressore VCS'
};


// riga «Impostato: …» di ogni passo, ricavata da a
function lzAuto(a) {
  const on = (k, n) => a[k] == null ? null : n + (a[k] ? ' acceso' : ' spento'), r = [];
  if (a.v) r.push('Vista ' + a.v);
  if ('s' in a) r.push(a.s ? 'impianto ' + SYS[a.s].n : 'nessun impianto');
  if (a.x != null) r.push(a.x ? 'Esploso al ' + Math.round(a.x * 100) + '%' : 'Esploso a zero');
  r.push(on('xr', 'Raggi X'), on('sens', 'Sensori'), on('flow', 'Flussi'));
  if (a.ts) r.push(a.ts > 1 ? 'Tempo ×3' : 'Tempo normale');
  if (a.f != null) r.push(a.f ? 'avaria ' + FAULTS[a.f] : 'Nessuna avaria');
  if (a.pieno) r.push('serbatoi pieni');
  if (a.eng) r.push({ off: 'motori su OFF', fly: 'Avvio rapido in volo', start: 'motori fermi, poi MOTORE 1 su MIN', apu: 'motori fermi, poi Modalità APU' }[a.eng]);
  if (a.coll != null) r.push('collettivo al ' + a.coll + '%');
  const t = r.filter(Boolean).join(', ');
  return t && t[0].toUpperCase() + t.slice(1) + '.';
}

var IN = {
  mgb: { ids: ['mgb', 'ruota_libera'], d: 'Interno della MGB, schema illustrativo (non il disegno Leonardo), carter tagliato. Ogni motore entra con la sua ruota libera e una coppia conica; i due pignoni muovono lo stesso ingranaggio collettore, che somma la potenza; l’epicicloidale riduce i giri fino a quelli del rotore.', p: {
    cassa: ['Carter', 'Contiene gli ingranaggi e l’olio, e regge l’albero rotore: attraverso la MGB passano al tetto della cabina il peso dell’elicottero e le forze del rotore.'],
    coppa: ['Coppa dell’olio', 'Il livello scende con l’avaria «perdita olio MGB». La pompa pesca da qui e manda l’olio, dopo il radiatore, a getti su ingranaggi e cuscinetti.'],
    rl: ['Ruota libera', 'Due metà: quella interna gira con la MGB, quella esterna (segni gialli) con la turbina libera del motore. Trasmette coppia solo dal motore alla MGB. Con il motore al minimo e il rotore al 100% le due metà girano a velocità diverse: il motore è svincolato.'],
    conici: ['Coppia conica d’ingresso', 'Gira di 90° il moto dell’albero del motore e fa il primo salto di riduzione.'],
    pignoni: ['Pignoni cilindrici', 'Uno per motore, ingranano lo stesso collettore: è qui che la potenza dei due motori si somma.'],
    collettore: ['Ingranaggio collettore', 'Ruota grande sull’albero del solare. Sotto ha la corona conica che muove l’uscita verso la coda, sul fianco la ruota della pompa olio: girano anche con un motore solo, e in autorotazione con il rotore.'],
    solare: ['Solare', 'Centro dell’epicicloidale, gira con il collettore.'],
    satelliti: ['Satelliti', 'Tre ruote tra solare e corona fissa: girano sul proprio perno e intanto rotolano lungo la corona, portandosi dietro il portasatelliti.'],
    corona: ['Corona fissa', 'Dentatura interna fissata al carter. Con la corona ferma il portasatelliti gira più piano del solare: rapporto 1 + corona/solare (qui 1 + 39/15 = 3,6).'],
    portasat: ['Portasatelliti', 'Porta i perni dei satelliti ed è un pezzo solo con l’albero rotore: è l’uscita lenta dell’epicicloidale.'],
    albero_rot: ['Albero rotore', 'Gira ai giri del rotore (NR) e porta la testa. Regge anche la spinta del rotore.'],
    uscita_coda: ['Uscita verso la coda', 'Pinione conico sotto il collettore: muove l’albero di coda, il freno rotore e la ventola del radiatore olio.'],
    pompa: ['Pompa olio MGB', 'Mossa dal collettore, gira solo con il rotore: a rotore fermo la pressione è zero. Si illumina quando manda olio.']
  } },
  pompa_idr: { ids: ['pompe_idr'], d: 'Interno della pompa dell’impianto 1 (quella del 2 è uguale), corpo tagliato. Schema illustrativo di una pompa a pistoni assiali a cilindrata variabile, il tipo usato di solito negli impianti idraulici aeronautici: il disegno della pompa dell’AW169 non è pubblico. Il blocco cilindri gira con l’albero; i pistoni appoggiano su un piatto inclinato che non gira, quindi a ogni giro escono e rientrano: aspirano da una luce della piastra e mandano in pressione dall’altra. Più il piatto è inclinato, più olio esce a ogni giro.', p: {
    cassa: ['Corpo pompa', 'Contiene il gruppo rotante ed è pieno d’olio: i trafilamenti dei pistoni finiscono qui e tornano al serbatoio con una linea di drenaggio, non disegnata.'],
    presa: ['Presa di moto dalla MGB', 'Ingranaggio degli accessori della MGB: la pompa gira con il rotore oppure, in modalità APU, con il motore 1 mentre il rotore è frenato. A motori fermi la pressione è zero.'],
    albero: ['Albero di comando', 'Scanalato, trascina il blocco cilindri. La pompa vera gira molto più veloce del rotore: qui è rallentata per vedere i pistoni.'],
    cilindri: ['Blocco cilindri', 'Gira con l’albero e porta 9 cilindri paralleli all’asse. Striscia a tenuta sulla piastra delle luci, su un velo d’olio.'],
    pistoni: ['Pistoni', 'Uno per cilindro, con il piede a sfera trattenuto sul piatto inclinato: girando con il blocco, ogni pistone fa una corsa avanti e indietro a ogni giro. Più il piatto è inclinato, più lunga è la corsa e più olio manda la pompa; a piatto dritto la corsa è zero.'],
    pattini: ['Pattini', 'Le scarpette sotto il piede di ogni pistone: scivolano sul piatto fermo su un velo d’olio in pressione, che arriva da un forellino nel pistone.'],
    piatto: ['Piatto inclinato', 'Non gira: oscilla sui due perni laterali e il suo angolo decide la cilindrata. Lo tengono in equilibrio la molla, che lo spinge verso l’inclinazione massima, e il pistone del compensatore, che lo raddrizza quando la pressione sale.'],
    compensatore: ['Compensatore di pressione', 'Pistone che riceve la pressione di mandata (tubo sottile). Quando arriva a quella di taratura (206 bar nel simulatore, un valore tipico) raddrizza il piatto: la pompa manda solo l’olio che i servoattuatori consumano. Con i comandi fermi il piatto è quasi dritto; muovendo i comandi la pressione cala un poco e il piatto si inclina. Schema semplificato: nelle pompe vere una piccola valvola tarata regola l’olio che arriva al pistone.'],
    molla: ['Molla del piatto', 'Spinge il piatto verso l’inclinazione massima. A pompa ferma o senza pressione vince lei: per questo la pompa riparte sempre a portata piena.'],
    piastra: ['Piastra delle luci', 'Ferma, con due feritoie a rene. Ogni cilindro passa davanti a una e poi all’altra una volta per giro: dalla luce dove il pistone si allontana entra l’olio aspirato, da quella dove si avvicina esce l’olio in pressione.'],
    aspirazione: ['Aspirazione', 'Dal serbatoio del modulo di potenza, a bassa pressione. Con l’avaria «perdita impianto idraulico 1» il serbatoio si svuota: prima la pressione regge e il piatto va al massimo per compensare, poi la pompa resta senza olio.'],
    mandata: ['Mandata', 'Olio in pressione verso il modulo di potenza e i servoattuatori. Le sfere corrono in proporzione alla portata, cioè giri della pompa per inclinazione del piatto. Il tubo si illumina con la pressione.']
  } },
  servo: { ids: ['servo_rotore', 'servo_coda'], d: 'Interno di un servoattuatore in tandem, corpo tagliato. Schema illustrativo di un tipo comune sugli elicotteri bimotore: il disegno dei servi dell’AW169 non è pubblico. Due corpi in fila sullo stesso stelo, ognuno alimentato da un impianto idraulico con la sua valvola a cassetto: se un impianto perde pressione l’altro muove ancora lo stelo. Il comando non spinge lo stelo, sposta i cassetti: il lavoro lo fa l’olio. Aperto dal rotore principale mostra il servo 1 dei 3, mosso da collettivo e ciclico; aperto dalla coda mostra l’attuatore di coda, mosso dalla pedaliera, che nel simulatore è disegnato allo stesso modo.', p: {
    corpo1: ['Corpo dell’impianto 1', 'Cilindro alimentato solo dall’impianto 1. È fissato alla struttura con l’attacco a sinistra e non si muove: si muove lo stelo.'],
    corpo2: ['Corpo dell’impianto 2', 'Uguale al primo e in fila con lui, alimentato solo dall’impianto 2. Il setto centrale tiene separati gli oli dei due impianti: una perdita in uno non svuota l’altro.'],
    stelo: ['Stelo', 'Un pezzo solo che attraversa i due corpi e porta i due pistoni. Con la testa a destra spinge il piatto fisso (nell’attuatore di coda, l’asta del passo).'],
    pistoni: ['Pistoni', 'Uno per corpo, sullo stesso stelo: le spinte dei due impianti si sommano. Con un impianto solo la spinta disponibile si dimezza; nel simulatore la velocità dello stelo resta la stessa.'],
    camera1: ['Camere dell’impianto 1', 'Il pistone divide il corpo in due camere. La valvola manda olio in pressione (azzurro acceso) in una e scarica l’altra (azzurro scuro) verso il ritorno: lo stelo va verso la camera scarica. A comando fermo il cassetto chiude tutte e due le camere e l’olio tiene lo stelo bloccato. Con l’avaria «perdita impianto idraulico 1» diventano grigie: niente pressione.'],
    camera2: ['Camere dell’impianto 2', 'Come quelle dell’impianto 1, con l’olio dell’impianto 2.'],
    cassetti: ['Valvole a cassetto', 'Un cassetto per corpo, sulla stessa asta. Spostato di pochi millimetri apre la mandata verso una camera e il ritorno dall’altra; centrato chiude tutto. La corsa è limitata da fermi: per questo lo stelo ha una velocità massima e il comando non può anticiparlo di molto.'],
    leva: ['Leva di somma', 'In alto riceve il comando, in basso è attaccata allo stelo, al centro muove i cassetti. Il comando sposta i cassetti; lo stelo si muove e, tirando la parte bassa della leva, li riporta al centro: si ferma appena raggiunge la posizione chiesta. È la retroazione meccanica. Questa leva inverte il verso: il comando va a sinistra, lo stelo a destra.'],
    comando: ['Asta del comando', 'Arriva dalla catena dei comandi: collettivo e ciclico per i servi del rotore principale, pedaliera per l’attuatore di coda. Il pilota muove solo i cassetti, non le pale: le forze delle pale le reggono i pistoni.'],
    condotti: ['Condotti alle camere', 'Collegano le luci di ogni valvola ai due capi del suo corpo e si colorano come la camera che alimentano.'],
    impianto1: ['Linee dell’impianto 1', 'Mandata (in alto) dal modulo di potenza dell’impianto 1 e ritorno al serbatoio. Le sfere corrono solo mentre lo stelo si muove: a comando fermo il servo non consuma olio.'],
    impianto2: ['Linee dell’impianto 2', 'Come quelle dell’impianto 1, dall’impianto 2.'],
    bypass: ['Valvole di by-pass', 'Una per corpo. Con l’impianto in pressione resta chiusa; quando la pressione manca una molla la apre e collega le due camere di quel corpo: il suo pistone scorre libero e non frena l’altro impianto. Con l’avaria «perdita impianto idraulico 1» si accende quella del corpo 1 e si vede l’olio passare da una camera all’altra.'],
    attacchi: ['Attacchi', 'A sinistra l’attacco del corpo alla struttura, a destra la testa dello stelo con lo snodo verso il piatto fisso. La staffa sullo stelo porta il movimento alla leva di somma.']
  } },
  avv_gen: { ids: ['avv_gen'], d: 'Interno dell’avviatore-generatore del motore 1 (quello del 2 è uguale), carcassa tagliata. Schema illustrativo di una macchina a corrente continua a spazzole da 28 V, come sugli AW109: tipo e tensione dei generatori dell’AW169 non sono pubblici. La stessa macchina fa due mestieri: all’avviamento riceve corrente dalla barra e gira come motore elettrico, trascinando il generatore di gas; a motore acceso è il generatore di gas a farla girare e lei restituisce corrente alla barra. Sopra, i due contattori che scelgono il verso della corrente e il regolatore (GCU).', p: {
    carcassa: ['Carcassa', 'Il giogo di ferro che chiude il circuito magnetico tra i poli e regge i cuscinetti dell’albero. Il lato sinistro si fissa con una flangia alla scatola accessori del motore; a destra, sotto la cuffia, la ventola.'],
    campo: ['Poli e avvolgimenti di campo', 'Quattro poli fissati alla carcassa, ognuno con il suo avvolgimento di rame: creano il campo magnetico in cui gira l’indotto. All’avviamento il campo è pieno e la coppia massima; da generatore il regolatore ne dosa la corrente: meno campo quando i giri salgono, più campo quando cresce il carico, così la tensione resta a 28,5 V. Si illuminano con la corrente di campo. Nelle macchine vere ogni polo porta due avvolgimenti (uno in serie con l’indotto per la coppia di spunto, uno comandato dal regolatore) e tra i poli ci sono poli ausiliari che aiutano la commutazione: qui uno solo, per chiarezza.'],
    indotto: ['Indotto', 'Il rotore: pacco di lamierini con 24 cave e, nelle cave, i conduttori di rame. Da motore la corrente nei conduttori immersi nel campo dà la coppia; da generatore il moto dei conduttori nel campo genera la tensione. Si illumina con la corrente: al massimo nello spunto (oltre 400 A nel simulatore), poi cala mentre il motore accelera, perché l’indotto che gira genera una tensione contraria a quella della barra.'],
    collettore: ['Collettore', 'Cilindro di lamelle di rame isolate tra loro, ognuna collegata a una bobina dell’indotto. Girando sotto le spazzole inverte la corrente nelle bobine al momento giusto: è lui che fa funzionare la macchina in corrente continua.'],
    spazzole: ['Spazzole', 'Blocchetti di carbone premuti da molle sul collettore, nei portaspazzole fissi (ottone). Portano la corrente dentro e fuori dall’indotto che gira. Si consumano: la loro lunghezza è un controllo di manutenzione tipico di queste macchine. Lo scintillio indica la corrente che passa.'],
    albero: ['Albero e sezione di rottura', 'Scanalato a sinistra, entra nella scatola accessori ed è mosso dal generatore di gas (NG), non dalla turbina libera: per questo può avviare il motore. Il collo sottile è la sezione di rottura: se la macchina si blocca, l’albero si spezza lì e protegge gli ingranaggi del motore.'],
    ventola: ['Ventola', 'Calettata sull’albero: fa passare l’aria tra poli e indotto per raffreddarli (sfere azzurre). A motore lento l’aria è poca e lo spunto scalda molto: per questo gli avviamenti consecutivi hanno limiti di tempo e di numero.'],
    morsetti: ['Morsetti', 'Sulla carcassa: a sinistra il morsetto di potenza (B+) dell’indotto, collegato ai due contattori; a destra quello del campo, collegato al regolatore. Il ritorno passa dalla massa della struttura.'],
    contattore_avv: ['Contattore di avviamento', 'Comandato dal FADEC: la bobina tira su il ponte mobile, che chiude i due contatti e collega la barra all’avviatore. Si apre al 50% di NG, quando il motore si sostiene da solo. Sotto lo spunto la tensione della barra cala di qualche volt: si vede nella riga BARRA V degli strumenti.'],
    contattore_linea: ['Contattore di linea', 'Mette il generatore in linea sulla barra. Lo chiude il regolatore quando la tensione del generatore è giusta e lo apre in caso di guasto o se la corrente rientra dalla barra nel generatore. Con l’avaria «generatore 1 fuori linea» resta aperto: la barra la alimentano l’altro generatore o le batterie.'],
    gcu: ['Regolatore (GCU)', 'Centralina di controllo del generatore. Misura la tensione e dosa la corrente nel campo per tenerla a 28,5 V (sfere sul cavo del campo), chiude il contattore di linea e protegge da sovratensione e guasti togliendo il campo. Verde mentre regola, rosso quando ha escluso il generatore.'],
    barra: ['Barra', 'La barra a 28 V del velivolo, a cui sono collegati anche le batterie e l’altro generatore. All’avviamento la corrente scende dalla barra nell’avviatore; a motore acceso risale dal generatore alla barra. Le sfere gialle seguono il verso della corrente.']
  } },
  serbatoio: { ids: ['serbatoi', 'tubo_carb', 'sfiati', 's_carb'], d: 'Interno del serbatoio sinistro (LH), che alimenta il motore 1 (il destro è speculare), guscio tagliato. Con fonte: la sacca in tessuto gommato dentro un guscio composito, tenuta ferma da schiuma ad alta densità, e il tubo che collega i due serbatoi (rapporto AAIB su G-VSKP); i due sfiati (AD EASA 2021-0238). Forma, misure, raccordi, pozzetto, filtro e drenaggio sono illustrativi: il disegno del serbatoio dell’AW169 non è pubblico. Il giallo è il carburante, che cala col consumo; sopra c’è l’aria entrata dallo sfiato.', p: {
    guscio: ['Guscio composito', 'Il contenitore rigido che regge la sacca e la fissa alla struttura sotto il pavimento della cabina. Insieme a sacca e schiuma risponde alla CS 29.952 sulla resistenza all’urto: in prova il serbatoio pieno cade da 15,2 m senza perdere carburante, e il fissaggio dei serbatoi in cabina deve tenere 20 g verso il basso.'],
    schiuma: ['Schiuma ad alta densità', 'Riempie lo spazio tra guscio e sacca e tiene ferma la sacca: senza, il carburante che sbatte nelle manovre la sposterebbe e la consumerebbe per sfregamento. In un urto aiuta a distribuire il carico sulla sacca.'],
    sacca: ['Sacca in tessuto gommato', 'La parete che tocca il carburante: tessuto antistrappo impregnato di gomma, flessibile. In un urto si deforma invece di spaccarsi come un serbatoio rigido e trattiene il carburante: è la difesa principale contro l’incendio dopo un atterraggio violento. Nelle versioni militari può essere autosigillante (brochure Leonardo): se un proiettile la fora, uno strato di gomma si gonfia a contatto col carburante e chiude il foro.'],
    carburante: ['Carburante', 'Cherosene per turbine (per esempio Jet A-1), circa 0,8 kg per litro. Nel simulatore ogni serbatoio tiene metà dei 1130 L del certificato di tipo, 565 L, di cui 10 inutilizzabili: quelli che restano nel pozzetto quando la pompa non pesca più. Il livello cala con il consumo del motore 1 e cambia con il travaso verso l’altro serbatoio.'],
    aria: ['Aria sopra il carburante', 'Lo spazio sopra il liquido. Mentre il carburante esce, l’aria rientra dallo sfiato e la pressione resta quella esterna. Con gli sfiati ostruiti non entra: la stessa aria occupa uno spazio che cresce, quindi la pressione cala (legge di Boyle, P·V costante) e la pompa del motore aspira sempre peggio, fino a spegnerlo. Diventa rossa con la depressione.'],
    sonda: ['Sonda di livello', 'Di solito capacitiva: due tubi concentrici formano un condensatore. Il carburante tra i tubi ha una costante dielettrica circa doppia di quella dell’aria, quindi la capacità cresce con il livello; l’elettronica la converte in quantità, la corregge con la densità e la mostra in kg. Il tipo di sonda dell’AW169 non è pubblico.'],
    pozzetto: ['Pozzetto e filtro', 'Il punto più basso della sacca: qui si raccolgono l’acqua e le impurità, più pesanti del carburante, e qui pesca, poco sopra il fondo, l’uscita al motore, così arriva al motore anche l’ultimo carburante utilizzabile. Il filtro a rete ferma le particelle grosse prima della linea.'],
    drenaggio: ['Valvola di drenaggio', 'Sotto il pozzetto: premendola si spilla un po’ di carburante in un contenitore trasparente, per vedere se c’è acqua (goccioline o uno strato sul fondo) o sporco. È un controllo prima del volo comune a quasi tutti gli aeromobili. Posizione illustrativa.'],
    uscita: ['Uscita e giunto a strappo', 'La linea che porta il carburante al motore 1, aspirato dalla pompa sul motore (nel modello niente pompe elettriche nei serbatoi); le sfere gialle sono il carburante che esce. L’anello rosso è un giunto autosigillante che si stacca in un urto: le due metà si chiudono da sole, così la linea strappata non svuota il serbatoio. La CS 29.952 chiede giunti così sulle linee del carburante, salvo dove non possono esserci spostamenti pericolosi; forma e posizione illustrative.'],
    valvola: ['Valvola d’intercettazione', 'Dopo il serbatoio, prima del vano motore (CS 29.1189): chiude il carburante del motore 1, per esempio in caso d’incendio. Qui è una valvola a sfera con attuatore elettrico: aperta (foro della sfera in linea) con il selettore su MIN o VOLO, chiusa su OFF. Tipo e comando illustrativi.'],
    collegamento: ['Tubo di collegamento', 'In basso, verso il serbatoio destro (RH): il carburante scorre da quello più pieno all’altro e i livelli restano pari (rapporto AAIB). Le sfere gialle danno il verso del travaso. Con un motore spento, l’altro consuma anche il carburante del lato fermo attraverso il tubo.'],
    sfiato: ['Sfiato', 'Parte dal cielo del serbatoio, sale sopra il serbatoio e scende fino all’uscita sotto il ventre: l’ansa in alto impedisce che il carburante esca dallo sfiato nelle manovre. Fa entrare aria al posto del carburante consumato (sfere azzurre) e lascia uscire i vapori. Con l’avaria «sfiati ostruiti» compare il tappo rosso: è ciò che ha causato il sigillante in eccesso dell’AD EASA 2021-0238.'],
    bocchettone: ['Bocchettone di rifornimento', 'Bocchettone generico per il rifornimento a gravità, con il collo che scende nel serbatoio. Il tappo chiude a tenuta: mal chiuso farebbe uscire carburante in volo. Tipo e posizione illustrativi.']
  } }
};

